import{_ as t,o,c as a,ag as d}from"./chunks/framework.BbSdnUwJ.js";const p=JSON.parse('{"title":"Sensors","description":"What each sensor type publishes, which one navigation reads, and the specifications the targets fill in.","frontmatter":{"title":"Sensors","description":"What each sensor type publishes, which one navigation reads, and the specifications the targets fill in."},"headers":[],"relativePath":"guide/advanced/sensors.md","filePath":"guide/advanced/sensors.md"}'),s={name:"guide/advanced/sensors.md"};function r(n,e,i,c,h,l){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="sensors" tabindex="-1">Sensors <a class="header-anchor" href="#sensors" aria-label="Permalink to &quot;Sensors&quot;">​</a></h1><p>A sensor is a part placed like any other; its component type says what the targets simulate and what navigation does with its data.</p><table tabindex="0"><thead><tr><th>Type</th><th>Publishes</th><th>Feeds</th></tr></thead><tbody><tr><td><code>Lidar</code></td><td><code>/scan</code></td><td>The costmaps and the localizer</td></tr><tr><td><code>Lidar3D</code></td><td><code>/lidar3d/points</code>, its middle ring on <code>/lidar3d/scan</code></td><td>The costmaps; the ring stands in for a laser</td></tr><tr><td><code>DepthCamera</code></td><td><code>/depth/image_raw</code>, <code>/depth/points</code></td><td>The costmaps; a scan made from its cloud stands in for a laser</td></tr><tr><td><code>RGBD</code></td><td><code>/rgbd/image_raw</code>, <code>/rgbd/depth/image_raw</code>, <code>/rgbd/points</code>, <code>/rgbd/camera_info</code></td><td>As for a depth camera</td></tr><tr><td><code>Camera</code></td><td><code>/camera/image_raw</code>, <code>/camera/camera_info</code></td><td>Nothing; the images are yours</td></tr><tr><td><code>IMU</code></td><td><code>/imu</code></td><td>Nothing; the readings are yours</td></tr><tr><td><code>Ultrasonic</code></td><td><code>/ultrasonic/range</code></td><td>The costmaps&#39; range layer</td></tr><tr><td><code>Range</code></td><td><code>/range</code></td><td>The costmaps&#39; range layer</td></tr><tr><td><code>Bumper</code></td><td><code>/bumper</code>, the contacts it feels</td><td><code>Check_contact</code></td></tr></tbody></table><p>The first sensor of a type gets these topics; a second one of the same type is suffixed with its component name. Each sensor&#39;s frame is its component name.</p><h2 id="which-sensor-navigation-uses" tabindex="-1">Which sensor navigation uses <a class="header-anchor" href="#which-sensor-navigation-uses" aria-label="Permalink to &quot;Which sensor navigation uses&quot;">​</a></h2><p>Nav2&#39;s costmaps mark what every point cloud sees, between 0.05 and 2 m above the ground. The costmaps and the localizer also read one planar scan, chosen in this order:</p><ol><li>the first <code>Lidar</code>;</li><li>the middle ring of the first <code>Lidar3D</code>;</li><li>a scan made from the first depth or RGBD camera&#39;s cloud, projected onto the ground plane.</li></ol><p>A range finder&#39;s reading marks the costmaps&#39; range layer. A robot with no range sensor at all is warned that it navigates blind.</p><h2 id="range-finders" tabindex="-1">Range finders <a class="header-anchor" href="#range-finders" aria-label="Permalink to &quot;Range finders&quot;">​</a></h2><p><code>Ultrasonic</code> measures with sound, <code>Range</code> with light: an infrared triangulation sensor or a time-of-flight one. Both report the nearest thing in a narrow cone along their <code>+x</code>, as <code>sensor_msgs/Range</code>, and differ in what the floor does. A sound pulse glancing off the floor does not come back, so an ultrasonic sensor&#39;s floor returns are dropped. Light does come back from a matte floor, so a <code>Range</code> sensor reads the floor wherever its cone meets it within its range, and the costmaps then mark the floor as an obstacle. The rule <code>sensing.range_clears_the_ground</code> warns about such a sensor at compile time and says how far to tilt it up, or how high to mount it.</p><p>A <code>Range</code> part states what it measures, from its maker&#39;s datasheet, in a <code>range</code> block: <code>min_m</code>, <code>max_m</code>, <code>field_of_view_rad</code> and <code>rate_hz</code>. A sensor that says only whether something is within one distance states that distance as both <code>min_m</code> and <code>max_m</code>; it reports <code>-inf</code> when something is there and <code>+inf</code> when nothing is, as <code>sensor_msgs/Range</code> defines it, and the range layer marks or clears its cone. An <code>Ultrasonic</code> part may state a <code>range</code> block too.</p><h2 id="specifications-the-targets-fill-in" tabindex="-1">Specifications the targets fill in <a class="header-anchor" href="#specifications-the-targets-fill-in" aria-label="Permalink to &quot;Specifications the targets fill in&quot;">​</a></h2><p>Except for a range finder&#39;s <code>range</code> block, a library part does not yet state a sensor&#39;s specification: its range, beam count, field of view or rate. Until it does, the targets use these, and declare each one in <code>compile.json</code>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Simulated as</th></tr></thead><tbody><tr><td><code>Lidar</code></td><td>360 beams over the full circle, 0.3 to 12 m, 10 Hz</td></tr><tr><td><code>Lidar3D</code></td><td>16 rings of 360 beams over 0.52 rad, 0.3 to 20 m, 10 Hz</td></tr><tr><td><code>Camera</code>, <code>DepthCamera</code>, <code>RGBD</code></td><td>320 by 240 pixels, 1.089 rad field of view, depth 0.1 to 5 m, 10 Hz</td></tr><tr><td><code>IMU</code></td><td>Ideal, 100 Hz</td></tr><tr><td><code>Ultrasonic</code></td><td>A cone of 9 by 9 beams, 0.52 rad, 0.02 to 4 m, 20 Hz unless the part states its own; the nearest return more than 0.05 m above the ground is the reading</td></tr><tr><td><code>Range</code></td><td>A cone of 9 by 9 beams over the part&#39;s stated cone, range and rate; the nearest return is the reading, the floor included</td></tr><tr><td><code>Bumper</code></td><td>An ideal contact switch over its collision box, 50 Hz</td></tr></tbody></table><h2 id="mounting" tabindex="-1">Mounting <a class="header-anchor" href="#mounting" aria-label="Permalink to &quot;Mounting&quot;">​</a></h2><p>A sensor looks along its own <code>+x</code>. The chassis connector it is glued to, together with the connector&#39;s <code>up</code>, decides which way that points on the robot; the TF tree carries the result, so a sensor mounted upside down still reports correctly in its own frame.</p>',16)])])}const g=t(s,[["render",r]]);export{p as __pageData,g as default};
